# FIXTURE 01: static site, MULTIPLE server_name values on one block, shared include.
server {
    listen 80;
    server_name example.lab www.example.lab static.example.lab;
    root /var/www/static;
    index index.html;
    include /etc/nginx/snippets/security-headers.conf;

    location / {
        try_files $uri $uri/ =404;
    }
}

